export const BUILTIN_SITE_FILES: Record<string, string> = {
  "riverside-segmented": "# yaml-language-server: $schema=../schema/site.schema.json\n#\n# Riverside after the work: the same plant as riverside-water, segmented into\n# IEC 62443 zones and conduits. It is the design lab S02 builds, and a\n# reference to compare your own design with. The labs start from the flat\n# plant, so most of them run on riverside-water instead.\n\nschema: zonesim-site/1\nid: riverside-segmented\nname: Riverside, segmented\ndescription: >-\n  The Riverside plant with a finished zone and conduit design: office, DMZ,\n  operations, control and safety zones, least-privilege conduits, Modbus\n  function code filtering, and vendor access through a jump host with MFA.\n  Use it to explore the target architecture. Most labs start from the flat\n  plant, so they run on riverside-water.\nextends: riverside-water\n\nhosts:\n  - { name: jump-01, mfa: true }\n\nzones:\n  - { name: site, remove: true }\n  - { name: enterprise, sl: 1, description: Office IT, hosts: [corp-pc] }\n  - { name: dmz, sl: 2, description: \"Between IT and OT: report copy and remote access\", hosts: [hist-dmz, jump-01] }\n  - { name: operations, sl: 2, description: Site operations, hosts: [historian] }\n  - { name: control, sl: 3, description: Supervisory control and the PLC, hosts: [hmi-01, ews-01, plc-1] }\n  - { name: safety, sl: 3, description: \"The safety instrumented system, on its own\", hosts: [sis-1] }\n\nconduits:\n  - { name: edge, remove: true }\n  - name: inet-dmz\n    zones: [internet, dmz]\n    rules:\n      - allow from vendor-laptop to jump-01 rdp\n  - name: ent-dmz\n    zones: [enterprise, dmz]\n    rules:\n      - allow from corp-pc to hist-dmz https\n  - name: ops-dmz\n    zones: [operations, dmz]\n    rules:\n      - allow from historian to hist-dmz https\n  - name: dmz-control\n    zones: [dmz, control]\n    rules:\n      - allow from jump-01 to ews-01 rdp\n  - name: ops-control\n    zones: [operations, control]\n    rules:\n      - allow from historian to plc-1 modbus fc 3,4\n  - name: ops-safety\n    zones: [operations, safety]\n    rules:\n      - allow from historian to sis-1 modbus fc 2,4\n  - name: control-safety\n    zones: [control, safety]\n    rules:\n      - allow from hmi-01 to sis-1 modbus fc read\n",
  "riverside-water": "# yaml-language-server: $schema=../schema/site.schema.json\n#\n# Riverside water treatment plant: the built-in ZoneSim site.\n# To make your own, start from sites/templates/my-site.yaml, which extends this\n# file and changes only what you need (names, IP addresses, setpoints ...).\n\nschema: zonesim-site/1\nid: riverside-water\nname: Riverside water treatment plant\ndescription: >\n  A small drinking water plant. An inlet pump fills a tank from the river,\n  chlorine is dosed into it, and the town draws water out. A PLC keeps the\n  level between two setpoints, and an independent safety system stops the\n  pump if the level gets too high. It starts on one flat network.\n\nprocess:\n  model: water-tank\n  tags:\n    source: river\n    consumer: town\n    tank: T-101\n    pump: P-101\n    dosing: P-201\n  params:\n    initialLevel: 55      # %\n    inflow: 1.2           # % of the tank per second while the inlet pump runs\n    demand: 0.5           # % of the tank per second drawn by the town\n    startLevel: 40        # %, default pump start level in auto mode\n    stopLevel: 80         # %, default pump stop level in auto mode\n    lowAlarm: 20          # %\n    highAlarm: 85         # %\n    highHighAlarm: 95     # %\n    tripLevel: 95         # %, default safety trip level\n    tripReset: 80         # %, the safety trip resets below this level\n    chlorineSetpoint: 1.5 # mg/L\n    chlorineInitial: 1.5  # mg/L\n    chlorineLow: 0.5      # mg/L, below this the water may be unsafe\n    chlorineHigh: 4.0     # mg/L, above this the plant is overdosing\n    chlorineTau: 15       # seconds for the residual to follow the setpoint\n    chlorineDecay: 40     # seconds for the residual to decay with dosing off\n\nhosts:\n  - { name: vendor-laptop, role: vendor, ip: 203.0.113.50, level: 5, kind: external, services: [], os: Windows 11, user: vendor, description: Remote vendor support laptop }\n  - { name: corp-pc, role: office, ip: 10.10.40.21, level: 4, kind: it, services: [rdp], os: Windows 11, user: alice, description: Office workstation (finance) }\n  - { name: hist-dmz, role: report-server, ip: 10.10.35.10, level: 3.5, kind: dmz, services: [https], os: Linux, user: svc-report, description: Historian copy for office reports }\n  - { name: jump-01, role: jump, ip: 10.10.35.20, level: 3.5, kind: dmz, services: [rdp, ssh], os: Windows Server 2022, user: vendor, description: Remote access jump host }\n  - { name: historian, role: historian, ip: 10.10.30.10, level: 3, kind: ot, services: [https, ssh], os: Windows Server 2019, user: svc-hist, description: Process historian }\n  - { name: hmi-01, role: hmi, ip: 10.10.20.10, level: 2, kind: ot, services: [http, rdp], os: Windows 10 LTSC, user: operator, description: Operator HMI }\n  - { name: ews-01, role: ews, ip: 10.10.20.30, level: 2, kind: ot, services: [rdp], os: Windows 10, user: engineer, description: Engineering workstation }\n  - { name: plc-1, role: plc, ip: 10.10.10.10, level: 1, kind: ot, services: [modbus, http], os: \"ZS-PLC 100, firmware 2.4.1\", description: Tank and dosing PLC }\n  - { name: sis-1, role: sis, ip: 10.10.10.20, level: 1, kind: ot, services: [modbus], os: \"ZS-SIS 20, firmware 1.8.0\", description: Safety instrumented system }\n\n# The network as found: everything on one flat zone, plus a port forward that\n# lets the vendor's laptop reach the engineering workstation directly.\nzones:\n  - { name: internet, description: Everything outside the site, hosts: [vendor-laptop] }\n  - name: site\n    description: \"The whole site network as found: office and plant on one flat network\"\n    hosts: [corp-pc, hist-dmz, jump-01, historian, hmi-01, ews-01, plc-1, sis-1]\n\nconduits:\n  - name: edge\n    zones: [internet, site]\n    rules:\n      - allow from vendor-laptop to ews-01 rdp\n\n# Controllers and their Modbus maps. Each point exposes a process signal.\n# Writable switches go in coils, writable numbers in holding registers,\n# read-only switches in discrete inputs, read-only numbers in input registers.\ndevices:\n  plc-1:\n    title: tank and dosing controller\n    vendor: ZoneSim Controls\n    product: ZS-PLC 100\n    revision: 2.4.1\n    points:\n      coil:\n        - { addr: 0, tag: P101_RUN_CMD, signal: pump.command, description: Inlet pump P-101 run command (used in manual mode only) }\n        - { addr: 1, tag: P201_ENABLE, signal: dosing.enable, description: Chlorine dosing pump P-201 enable }\n        - { addr: 2, tag: AUTO_MODE, signal: control.auto, description: \"1 = automatic level control, 0 = manual\" }\n      di:\n        - { addr: 0, tag: P101_RUNNING, signal: pump.running, description: Inlet pump P-101 is running }\n        - { addr: 1, tag: P201_RUNNING, signal: dosing.running, description: Dosing pump P-201 is running }\n        - { addr: 2, tag: LAH_101, signal: alarm.high, description: Tank level high alarm }\n        - { addr: 3, tag: LAL_101, signal: alarm.low, description: Tank level low alarm }\n        - { addr: 4, tag: OVERFLOW, signal: alarm.overflow, description: Tank T-101 is overflowing }\n      ir:\n        - { addr: 0, tag: LT_101, signal: level, description: Tank T-101 level, units: \"tenths of a %, 623 = 62.3 %\" }\n        - { addr: 1, tag: AIT_201, signal: chlorine, description: Chlorine residual, units: \"hundredths of mg/L, 150 = 1.50 mg/L\" }\n      hr:\n        - { addr: 0, tag: LSP_START, signal: setpoint.start, description: Pump start level in auto mode, units: tenths of a % }\n        - { addr: 1, tag: LSP_STOP, signal: setpoint.stop, description: Pump stop level in auto mode, units: tenths of a % }\n        - { addr: 2, tag: CL_SETPOINT, signal: setpoint.chlorine, description: Chlorine dosing setpoint, units: hundredths of mg/L }\n  sis-1:\n    title: safety instrumented system\n    vendor: ZoneSim Controls\n    product: ZS-SIS 20\n    revision: 1.8.0\n    points:\n      coil:\n        - { addr: 0, tag: HH_BYPASS, signal: sis.bypass, description: \"Maintenance bypass of the high-high level trip (1 = bypassed)\" }\n      di:\n        - { addr: 0, tag: TRIP_ACTIVE, signal: sis.tripped, description: \"High-high trip active, inlet pump held off\" }\n        - { addr: 1, tag: BYPASS_ACTIVE, signal: sis.bypassed, description: High-high trip is bypassed }\n      ir:\n        - { addr: 0, tag: LT_102, signal: sis.level, description: Independent tank level transmitter, units: tenths of a % }\n      hr:\n        - { addr: 0, tag: LSHH_SP, signal: sis.trip_level, description: High-high trip level, units: tenths of a % }\n\n# What the operator screen shows, and where it gets its data.\nhmi:\n  host: hmi-01\n  device: plc-1\n  timeout: 6   # seconds without data before the HMI shows COMM FAIL\n\n# Traffic the plant generates by itself.\npolling:\n  - { from: hmi-01, to: plc-1, service: modbus, fc: [3, 4], every: 2 }\n  - { from: hmi-01, to: sis-1, service: modbus, fc: [2], every: 5 }\n  - { from: historian, to: plc-1, service: modbus, fc: [4], every: 5 }\n  - { from: historian, to: sis-1, service: modbus, fc: [4], every: 10 }\n  - { from: historian, to: hist-dmz, service: https, every: 10 }\n  - { from: corp-pc, to: hist-dmz, service: https, every: 30 }\n\n# Data flows the plant needs. Blocking one breaks something.\nflows:\n  - { id: hmi-plc, why: Operators watch and control the process from the HMI., from: hmi-01, to: plc-1, service: modbus, fc: [1, 2, 3, 4, 5, 6] }\n  - { id: hmi-sis, why: Operators see the safety system status on the HMI., from: hmi-01, to: sis-1, service: modbus, fc: [2, 4] }\n  - { id: historian-plc, why: The historian records the process values., from: historian, to: plc-1, service: modbus, fc: [3, 4] }\n  - { id: historian-sis, why: The historian records the safety system values., from: historian, to: sis-1, service: modbus, fc: [2, 4] }\n  - { id: ews-plc, why: Engineers maintain the PLC settings from the engineering workstation., from: ews-01, to: plc-1, service: modbus, fc: [1, 2, 3, 4, 5, 6, 15, 16, 43] }\n  - { id: historian-replica, why: The historian copies data to the DMZ so the office never touches the plant., from: historian, to: hist-dmz, service: https }\n  - { id: office-reports, why: Office staff read production reports from the DMZ copy., from: corp-pc, to: hist-dmz, service: https }\n  - id: vendor-support\n    why: The vendor supports the plant remotely, directly or through the jump host.\n    paths:\n      - [{ from: vendor-laptop, to: jump-01, service: rdp }, { from: jump-01, to: ews-01, service: rdp }]\n      - [{ from: vendor-laptop, to: ews-01, service: rdp }]\n\n# What the IDS sensor considers normal.\nids:\n  writers:\n    plc-1: [hmi-01, ews-01]\n  safety: [sis-1]          # any write to these is critical\n  identify: [ews-01]       # hosts allowed to read device identification\n"
};

