  "my-water-plant": "# yaml-language-server: $schema=https://sdtslmn.github.io/zonesim/schema/site.schema.json\n#\n# Your own site, starting from the built-in Riverside plant. Change what you\n# need and delete the rest: anything you leave out comes from riverside-water.\n#\n# Use it in the browser: Site tab, then \"Load a site file\".\n# Check it from a clone of the repo: npm run validate -- my-site.yaml\n# Help on every field: https://github.com/sdtslmn/zonesim/blob/main/docs/help/customize.md\n\nschema: zonesim-site/1\nid: my-water-plant\nname: Northgate water works\ndescription: A copy of the Riverside plant with our own names, addresses and setpoints.\nextends: riverside-water\n\n# Rename hosts or zones. Every reference (zones, rules, devices, flows, IDS)\n# is updated for you. Labs keep working because they use roles, not names.\nrename:\n  plc-1: tank-plc\n  hmi-01: scada-hmi\n\n# Change fields of existing hosts (matched by name, the new name after a\n# rename). Add a host by giving a new name with all its fields.\nhosts:\n  - { name: tank-plc, ip: 192.168.10.10, os: \"NA-500, firmware 3.1.0\", description: Reservoir tank PLC }\n  - { name: sis-1, ip: 192.168.10.20 }\n  - { name: scada-hmi, ip: 192.168.20.10 }\n  - { name: ews-01, ip: 192.168.20.30 }\n  - { name: historian, ip: 192.168.30.10 }\n\n# Process names and numbers. Any parameter you leave out keeps its default.\nprocess:\n  tags:\n    source: reservoir\n    consumer: city\n  params:\n    stopLevel: 75\n    inflow: 1.5\n\n# Controller details. Point maps are inherited unless you replace a table.\n# Here the setpoints live at holding registers 100 to 102, as in our PLC\n# program. A table you give replaces the inherited one completely.\ndevices:\n  tank-plc:\n    vendor: Northgate Automation\n    product: NA-500\n    revision: 3.1.0\n    points:\n      hr:\n        - { addr: 100, tag: LIC101_SP_START, signal: setpoint.start, description: Pump start level in auto mode, units: tenths of a % }\n        - { addr: 101, tag: LIC101_SP_STOP, signal: setpoint.stop, description: Pump stop level in auto mode, units: tenths of a % }\n        - { addr: 102, tag: AIC201_SP, signal: setpoint.chlorine, description: Chlorine dosing setpoint, units: hundredths of mg/L }\n"
